INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Huruf Sirilik Terlihat Menakutkan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Banyak pemula ingin belajar bahasa Rusia tetapi mundur begitu melihat tulisannya: Д, Ж, Ф, Ю, Я. Huruf-huruf Sirilik terlihat asing dan menakutkan, padahal alfabet Rusia hanya punya 33 huruf — lebih sedikit dari alfabet Jepang hiragana yang 46. Kabar baiknya: bahasa Rusia dibaca persis seperti ditulis, tidak seperti bahasa Inggris yang penuh pengecualian. Sekali kamu menguasai alfabetnya, kamu bisa membaca hampir semua kata Rusia walau belum paham artinya.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: 33 Huruf dengan Tiga Kelompok$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Alfabet Sirilik Rusia terdiri dari 33 huruf: 10 vokal, 21 konsonan, dan 2 tanda (tanda keras Ъ dan tanda lunak Ь yang tidak berbunyi sendiri). Trik tercepat menguasainya adalah membagi huruf menjadi tiga kelompok. Kelompok pertama: huruf yang bentuk DAN bunyinya sama dengan Latin — А (a), К (k), М (m), О (o), Т (t), Е (ye/seperti e). Kelompok kedua: huruf palsu — bentuknya seperti Latin tetapi bunyinya beda, inilah jebakan terbesar: В dibaca v (bukan b), Н dibaca n (bukan h), Р dibaca r (bukan p), С dibaca s (bukan c), Х dibaca kh (bukan x), У dibaca u. Kelompok ketiga: huruf yang benar-benar baru seperti Ж (zh), Ш (sh), Щ (shch), Ю (yu), Я (ya), Ц (ts), Ч (ch).$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat dan Persiapan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Tabel alfabet Sirilik lengkap dengan transliterasi (cetak atau simpan di HP)$txt$, $txt$Buku catatan khusus untuk latihan menulis huruf$txt$, $txt$Aplikasi kamus Rusia-Indonesia untuk melihat contoh kata$txt$, $txt$Spidol warna: satu warna untuk huruf palsu agar mudah diingat$txt$, $txt$Waktu 15 menit per hari selama 2 minggu$txt$]::text[]));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah-langkah Menguasai Sirilik$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$txt$Langkah 1 — Kuasai kelompok pertama (1 hari): hafalkan А, К, М, О, Т, Е. Langsung coba baca kata seperti МАМА (mama), КОТ (kucing).$txt$, $txt$Langkah 2 — Taklukkan huruf palsu (3 hari): tulis В, Н, Р, С, Х, У dengan warna mencolok beserta bunyi sebenarnya. Baca kata seperti НОС (hidung, dibaca nos), СОК (jus, dibaca sok).$txt$, $txt$Langkah 3 — Pelajari huruf baru (4 hari): Ж, Ш, Щ, Ц, Ч, Ю, Я, ditambah tanda Ь/Ъ. Fokus pada pasangan yang mirip: Ш vs Щ, Е vs Ё.$txt$, $txt$Langkah 4 — Latihan membaca kata nyata (setiap hari): baca papan nama, menu, atau judul berita Rusia. Target: membaca 20 kata per hari.$txt$, $txt$Langkah 5 — Latihan menulis tangan: tulis huruf Sirilik dengan tangan, bukan hanya membaca. Menulis mempercepat hafalan dua kali lipat.$txt$, $txt$Langkah 6 — Uji diri: tulis nama sendiri dan nama teman dalam Sirilik, lalu baca keras-keras.$txt$]::text[]));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Jebakan terbesar adalah huruf palsu: membaca РЕСТОРАН sebagai restoran memang benar (dibaca restoran), tetapi membaca НЕТ sebagai het adalah salah — seharusnya nyet (artinya tidak). Kesalahan umum kedua: mengabaikan tekanan kata (aksen). Dalam bahasa Rusia, vokal O yang tidak bertekanan dibaca seperti A — misalnya МОСКВА dibaca maskva, bukan moskva. Kesalahan ketiga: terburu-buru ke tata bahasa sebelum alfabet benar-benar dikuasai. Tanpa fondasi alfabet yang kuat, semua pelajaran berikutnya akan goyah.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$Bisa membaca 20 kata Rusia sederhana tanpa melihat tabel alfabet$txt$, $txt$Bisa menulis nama sendiri dalam huruf Sirilik dengan benar$txt$, $txt$Tidak lagi tertukar membaca huruf palsu (В, Н, Р, С, Х)$txt$, $txt$Bisa membedakan Ш, Щ, Ж saat membaca teks pendek$txt$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Hidung Tersumbat Mengganggu Aktivitas$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Hidung tersumbat membuat sulit bernapas, mengganggu tidur, menurunkan nafsu makan, dan bikin kepala terasa berat. Hampir semua orang mengalaminya saat pilek atau alergi kambuh. Kabar baiknya, sebagian besar kasus hidung tersumbat bisa diatasi di rumah dengan cara sederhana dan aman. Catatan: artikel ini berisi informasi umum, bukan pengganti nasihat medis. Jika ragu, konsultasikan ke dokter.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Mengapa Hidung Tersumbat$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Hidung tersumbat terjadi karena pembuluh darah di dalam hidung membengkak dan lapisan lendir memproduksi ingus berlebih. Penyebab paling umum adalah pilek (infeksi virus), alergi (debu, bulu hewan, serbuk sari), sinusitis (radang rongga sinus), perubahan cuaca dingin, dan terkadang polip hidung. Pada pilek biasa, sumbatan biasanya membaik dalam 7–10 hari. Pada alergi, sumbatan bisa datang-pergi tergantung paparan pemicu.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Persiapan Alat dan Bahan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Air hangat dan handuk bersih untuk kompres/uap$txt$, $txt$Garam dapur untuk membuat larutan saline (air garam)$txt$, $txt$Neti pot atau botol semprot hidung bila ada$txt$, $txt$Minuman hangat (teh, air jahe, sup)$txt$, $txt$Bantal tambahan untuk meninggikan posisi kepala saat tidur$txt$, $txt$Tisu lembut$txt$]::text[]));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah-langkah Mengatasi$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$txt$Langkah 1 — Hirup uap air hangat: tuang air panas ke baskom, dekatkan wajah (jaga jarak aman agar tidak kepanasan), hirup uapnya 10–15 menit. Uap membantu mengencerkan lendir.$txt$, $txt$Langkah 2 — Bilas hidung dengan larutan saline: campur 1 sendok teh garam ke 500 ml air matang hangat. Semprotkan atau alirkan perlahan ke satu lubang hidung. Ini membersihkan lendir dan alergen.$txt$, $txt$Langkah 3 — Kompres hangat: tempelkan handuk hangat ke area hidung dan pipi untuk meredakan tekanan.$txt$, $txt$Langkah 4 — Tinggikan kepala saat tidur: gunakan bantal tambahan agar lendir tidak menumpuk dan napas lebih lega.$txt$, $txt$Langkah 5 — Minum cukup cairan hangat: membantu mengencerkan lendir dari dalam.$txt$, $txt$Langkah 6 — Hindari pemicu: jauhkan diri dari asap rokok, debu, dan udara terlalu dingin atau kering.$txt$]::text[]));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko: Jangan Lakukan Ini$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Hindari pemakaian obat semprot hidung dekongestan (misalnya yang mengandung oxymetazoline) lebih dari 3 hari berturut-turut — pemakaian berlebihan justru menyebabkan hidung makin tersumbat saat obat berhenti (efek rebound). Jangan meniup hidung terlalu keras karena dapat mendorong lendir ke saluran telinga dan menyebabkan radang telinga. Jangan mencampur obat flu tanpa membaca aturan pakai, dan jangan memberi obat flu dewasa kepada anak kecil tanpa petunjuk dokter.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Tanda Bahaya: Kapan Harus ke Dokter$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$Hidung tersumbat lebih dari 10 hari tanpa membaik$txt$, $txt$Disertai demam tinggi di atas 38,5 derajat$txt$, $txt$Nyeri hebat di wajah atau gigi atas (curiga sinusitis)$txt$, $txt$Ingus berwarna hijau pekat berbau busuk$txt$, $txt$Keluar darah dari hidung yang tidak berhenti$txt$, $txt$Sumbatan hanya di satu sisi hidung dalam waktu lama (curiga polip atau benda asing)$txt$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Sungai Kapuas: Sang Terpanjang$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Sungai Kapuas di Kalimantan Barat adalah sungai terpanjang di Indonesia dengan panjang sekitar 1.143 kilometer. Ia berhulu di Pegunungan Muller dan bermuara di Selat Karimata dekat Pontianak. Kapuas menjadi urat nadi transportasi masyarakat pedalaman Kalimantan — perahu dan kapal motor adalah angkutan utama karena jalan darat terbatas. Sungai ini juga rumah bagi ikan arwana super red yang terkenal dan dilindungi.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Sungai Mahakam: Jantung Kalimantan Timur$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Sungai Mahakam membentang sekitar 920 kilometer dari dataran tinggi Kalimantan Timur hingga Selat Makassar. Mahakam terkenal sebagai habitat pesut Mahakam, lumba-lumba air tawar yang kini terancam punah dan hanya tersisa ratusan ekor. Sungai ini juga menjadi jalur utama pengangkutan batu bara, yang di satu sisi menopang ekonomi tetapi di sisi lain mengancam kelestarian sungai.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Sungai Barito: Raksasa Kalimantan Selatan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Sungai Barito memiliki panjang sekitar 890 kilometer, mengalir dari Kalimantan Tengah hingga bermuara di Laut Jawa dekat Banjarmasin. Barito dan anak-anak sungainya membentuk lahan basah rawa gambut yang sangat luas — ekosistem penting penyimpan karbon dunia. Pasar terapung di Banjarmasin, tempat pedagang berjualan dari atas perahu, adalah ikon budaya yang lahir dari sungai ini.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Sungai Musi dan Bengawan Solo$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Sungai Musi di Sumatra Selatan (sekitar 750 km) sejak abad ke-7 adalah jalur perdagangan Kerajaan Sriwijaya yang menguasai maritim Asia Tenggara; kini Jembatan Ampera di Palembang menjadi ikonnya. Sementara itu Bengawan Solo (sekitar 600 km) adalah sungai terpanjang di Jawa — diabadikan lagu keroncong Gesang — menjadi sumber irigasi sawah yang luas sekaligus langganan banjir musiman, menunjukkan dua wajah sungai: pemberi kehidupan dan ancaman bencana.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Peran Sungai bagi Indonesia$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Sebagai negara kepulauan bercuah hujan tinggi, Indonesia memiliki ribuan sungai: jalur transportasi, sumber air minum, irigasi, pembangkit listrik, dan habitat hayati. Namun mereka menghadapi pencemaran limbah, sedimentasi akibat deforestasi, dan alih fungsi lahan. Menjaga sungai berarti menjaga masa depan air bersih Indonesia.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Apa Itu 5G$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$5G adalah teknologi jaringan seluler generasi kelima, penerus 4G/LTE. Setiap generasi (1G suara analog, 2G SMS, 3G internet mobile, 4G video streaming) membawa lompatan kemampuan. 5G dirancang bukan sekadar untuk HP lebih cepat, tetapi sebagai fondasi bagi miliaran perangkat yang saling terhubung — dari mobil otonom hingga sensor pabrik — dalam visi yang disebut Internet of Things.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Seberapa Cepat 5G$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Secara teori, 5G mampu mencapai kecepatan unduh 10–20 Gbps — sekitar 100 kali lebih cepat dari 4G pada kondisi ideal. Yang lebih revolusioner adalah latensinya: waktu tunda komunikasi bisa di bawah 1 milidetik, dibanding 30–50 milidetik pada 4G. Artinya, perintah dari jarak jauh terasa nyaris seketika. Dalam praktik sehari-hari, pengguna 5G umumnya merasakan kecepatan beberapa ratus Mbps hingga 1 Gbps tergantung lokasi dan kepadatan pengguna.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Tiga Pita Frekuensi 5G$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$5G bekerja di tiga rentang frekuensi dengan karakter berbeda. Pita rendah (di bawah 1 GHz) menjangkau area luas dan menembus bangunan, tetapi kecepatannya hanya sedikit di atas 4G. Pita menengah (1–6 GHz) adalah titik seimbang antara jangkauan dan kecepatan — inilah tulang punggung 5G di banyak negara. Pita tinggi atau mmWave (di atas 24 GHz) memberi kecepatan ekstrem tetapi jangkauannya hanya ratusan meter dan mudah terhalang dinding, sehingga cocok untuk stadion atau kawasan padat.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Penerapan: dari Dunia hingga Indonesia$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Latensi super rendah 5G membuka aplikasi mustahil di 4G: operasi bedah jarak jauh, kendaraan otonom yang berkomunikasi dalam sepersekian detik, pabrik pintar, dan kota pintar bersensor. Indonesia menggelar 5G komersial sejak 2021 di kota besar dan memperluas bertahap; tantangannya adalah pemerataan ke daerah 3T dan daya beli perangkat. Pemerintah menargetkan 5G sebagai pengungkit ekonomi digital menuju Indonesia Emas 2045.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Mitos dan Fakta Keamanan 5G$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Beredar klaim bahwa 5G menyebabkan penyakit atau disebarkan lewat menara. Konsensus badan kesehatan dunia, termasuk WHO, menyatakan bahwa paparan gelombang radio 5G berada di bawah batas aman internasional dan tidak ada bukti ilmiah yang menghubungkannya dengan penyakit — 5G menggunakan radiasi non-pengion yang tidak merusak DNA, berbeda dengan sinar-X. Yang patut diwaspadai justru hoaksnya, bukan teknologinya.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$txt$Menjelaskan pengertian gen, kromosom, dan DNA sebagai materi genetik$txt$, $txt$Membedakan sifat dominan dan resesif$txt$, $txt$Menerapkan hukum Mendel dalam persilangan sederhana$txt$, $txt$Memberi contoh pewarisan sifat pada manusia dan tumbuhan$txt$]::text[]));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Materi: Gen, Kromosom, dan DNA$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Setiap makhluk hidup mewarisi sifat dari induknya melalui materi genetik. Materi genetik tersusun dari DNA (asam deoksiribonukleat) yang membentuk gen — unit pewarisan sifat seperti warna bunga atau golongan darah. Gen-gen tersusun berderet pada kromosom di dalam inti sel. Manusia memiliki 46 kromosom (23 pasang): 23 dari ayah dan 23 dari ibu. Inilah alasan kamu mirip kedua orang tuamu sekaligus unik.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Hukum Mendel, Dominan, dan Resesif$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Gregor Mendel menemukan dua hukum pewarisan lewat kacang ercis. Hukum I (segregasi): pasangan alel memisah saat pembentukan sel kelamin. Hukum II (pengelompokan bebas): gen sifat berbeda diwariskan independen. Alel dominan (huruf besar, mis. B) menampakkan sifatnya meski satu salinan; alel resesif (huruf kecil, mis. b) hanya tampak bila berpasangan (bb). Contoh: bunga ungu (B) dominan terhadap putih (b), sehingga persilangan Bb x Bb menghasilkan rasio 3 ungu : 1 putih. Pada manusia, lesung pipi dominan, sedangkan golongan darah O resesif terhadap A dan B.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Contoh Persilangan dengan Tabel Punnett$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Misalkan persilangan dua tanaman bergenotipe Bb. Buat tabel Punnett 2x2: baris berisi B dan b dari induk pertama, kolom berisi B dan b dari induk kedua. Hasilnya: BB (ungu), Bb (ungu), Bb (ungu), bb (putih) — 75 persen ungu, 25 persen putih. Cara ini bisa dipakai memprediksi semua persilangan satu sifat beda, termasuk golongan darah manusia.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Latihan Soal$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$txt$1. Jelaskan perbedaan gen, kromosom, dan DNA!$txt$, $txt$2. Tanaman bunga merah (MM) disilangkan dengan bunga putih (mm). Tentukan genotipe dan fenotipe keturunannya!$txt$, $txt$3. Seorang ayah bergolongan darah A heterozigot (IAIO) dan ibu bergolongan darah O (IOIO). Golongan darah apa saja yang mungkin dimiliki anak mereka?$txt$]::text[]));
