INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$1. DNA adalah molekul pembawa informasi genetik; gen adalah segmen DNA yang mengode satu sifat; kromosom adalah struktur tempat gen-gen tersusun di inti sel.$txt$, $txt$2. Semua keturunan bergenotipe Mm dan berfenotipe bunga merah (100 persen), karena alel M dominan.$txt$, $txt$3. Anak bisa bergolongan darah A (IAIO, 50 persen) atau O (IOIO, 50 persen).$txt$]::text[]));
