INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$txt$Memahami pengertian pecahan sebagai bagian dari keseluruhan$txt$, $txt$Membaca dan menulis pecahan sederhana (setengah, sepertiga, seperempat)$txt$, $txt$Menentukan pecahan senilai$txt$, $txt$Membandingkan dua pecahan sederhana$txt$]::text[]));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Pecahan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Pecahan adalah bagian dari sesuatu yang utuh. Bayangkan satu kue ulang tahun dipotong menjadi 2 bagian sama besar — tiap potongnya adalah setengah kue, ditulis 1/2. Angka di atas garis disebut pembilang (berapa bagian yang diambil), angka di bawah garis disebut penyebut (menjadi berapa bagian sama besar kue dipotong). Jadi pada 1/2, pembilangnya 1 dan penyebutnya 2.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Membaca Pecahan dan Pecahan Senilai$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Pecahan-pecahan yang sering dipakai: 1/2 dibaca setengah, 1/3 dibaca sepertiga, 1/4 dibaca seperempat, 3/4 dibaca tiga perempat. Pecahan senilai adalah pecahan yang penulisannya beda tetapi nilainya sama — contohnya 1/2 = 2/4. Mengapa? Bayangkan kue dipotong 2 bagian, lalu tiap bagian dipotong lagi menjadi 2: sekarang ada 4 potong, dan 2 potong sama besar dengan setengah kue semula. Cara mendapat pecahan senilai: kalikan pembilang dan penyebut dengan angka yang sama, misalnya 1/2 = 2/4 = 3/6.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Membandingkan Pecahan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Bila penyebutnya sama, bandingkan pembilangnya: semakin besar pembilang, semakin besar nilainya — 3/4 lebih besar dari 1/4. Bila penyebutnya beda, samakan dulu: 1/2 menjadi 3/6 dan 1/3 menjadi 2/6, jadi 1/2 lebih besar dari 1/3. Logikanya sederhana: kue yang dipotong 2 menghasilkan potongan lebih besar daripada yang dipotong 3. Pecahan juga ada di kehidupan sehari-hari: setengah jam sama dengan 30 menit, dan 1/4 semangka artinya satu dari empat potong yang sama besar.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Latihan Soal$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$txt$1. Tuliskan pembilang dan penyebut dari pecahan 3/5!$txt$, $txt$2. Ibu memotong pizza menjadi 8 bagian sama besar. Ayah makan 3 bagian. Tuliskan pecahan bagian pizza yang dimakan ayah!$txt$, $txt$3. Manakah yang lebih besar: 2/4 atau 3/4? Jelaskan!$txt$, $txt$4. Tuliskan dua pecahan yang senilai dengan 1/3!$txt$]::text[]));
