INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$1. Pembilang = 3, penyebut = 5.$txt$, $txt$2. 3/8.$txt$, $txt$3. 3/4 lebih besar, karena penyebutnya sama (4) dan pembilang 3 lebih besar dari 2.$txt$, $txt$4. Contoh: 2/6 dan 3/9 (jawaban lain yang benar juga diterima).$txt$]::text[]));
